15	    // 100 G base + 10 G first insurance + 5 G fee = 115 G
16	    const result = runScenario({
17	      customer: { yearsWithMHPCO: 0 },
18	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
19	    });
20	
21	    expect(result).toEqual({ results: [{ premium: 115 }] });
22	  });
23	  it.todo("amulet → base premium 60 G");
24	  it.todo("staff → base premium 80 G");
25	  it.todo("potion → base premium 40 G");
