35	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
36	
37	  // --- Item-specific modifiers ------------------------------------------
38	  it.todo("cursed sword adds 50 % of its base premium as risk surcharge");
39	  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %)");
40	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
41	  it.todo("cursed sword with enchantment 5 → both surcharges apply");
42	
43	  // --- Policy-wide modifiers ---------------------------------------------
44	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
45	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
46	  it.todo("first quote carries a 10 % initial assessment surcharge");
47	  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");
48	  it.todo("first insurance surcharge still applies on a follow-up contract");
49	
50	  // --- Modifier scope on multi-item policies ------------------------------
51	  it.todo(
52	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
53	  );
54	
55	  // --- Rounding ------------------------------------------------------------
56	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
57	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
58	
59	  // --- Integration examples -------------------------------------------------
60	  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
61	  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
62	
63	  // --- Claim: standard reimbursement ----------------------------------------
64	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
65	  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
66	
67	  // --- Claim: special clauses ------------------------------------------------
68	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
69	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G");
70	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
71	  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
72	
73	  // --- Claim: deductible per damage event -------------------------------------
74	  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G");
75	
76	  // --- Claim: cap ---------------------------------------------------------------
77	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
78	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
79	  it.todo("cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
80	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G");
81	  it.todo("sword, two successive claims of 1500 G → first payout 1400 G, remaining cap 600 G");
82	  it.todo("sword, second claim of 1500 G → payout 600 G, remaining cap 0 G");
83	
84	  // --- Claim: multiple items of the same type -------------------------------------
85	  it.todo("two swords insured, two sword damages → each damage gets its own deductible");
86	  it.todo("more damage entries of a type than insured → claim rejected (error)");
87	
