const SWORD_BASE_PREMIUM = 100;

const basePremium = (_item: Item): number => SWORD_BASE_PREMIUM;

const quote = (items: Item[]): QuoteResult => {
  const policyBase = items
    .map(basePremium)
    .reduce((total, premium) => total + premium, 0);

  return {
    premium:
      policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE,
  };
};

